@override_settings(ROOT_URLCONF=__name__)
class ReadonlyRelationTests(TestCase):
    @classmethod
    def setUpTestData(cls):
        cls.user = User.objects.create_user('viewer', is_staff=True)
        cls.section = Section.objects.create(name='<Section & details>')
        cls.other_section = Section.objects.create(name='Other section')
        cls.article = Article.objects.create(
            title='Article', content='Content', date=datetime.datetime(2020, 1, 1),
            section=cls.section, another_section=cls.other_section,
        )
        cls.pizza = Pizza.objects.create(name='Pizza')
        cls.topping = Topping.objects.create(name='<Cheese & tomato>')
        cls.other_topping = Topping.objects.create(name='Olives')
        cls.pizza.toppings.add(cls.topping, cls.other_topping)

    def setUp(self):
        self.client.force_login(self.user)

    def grant(self, *codenames):
        self.user.user_permissions.add(*Permission.objects.filter(
            content_type__app_label='admin_views', codename__in=codenames,
        ))

    def change_url(self, obj):
        return reverse('readonly_admin:admin_views_%s_change' % obj._meta.model_name, args=(obj.pk,))

    def link(self, obj):
        return format_html('<a href="{}">{}</a>', self.change_url(obj), obj)

    def contents(self, response, name):
        for fieldset in response.context['adminform']:
            for line in fieldset:
                for field in line:
                    if field.field['name'] == name:
                        return field.contents()
        self.fail('Readonly field %s was not found.' % name)

    def test_foreign_key_view_permission(self):
        self.grant('view_article', 'view_section')
        response = self.client.get(self.change_url(self.article))
        self.assertEqual(response.status_code, 200)
        self.assertHTMLEqual(self.contents(response, 'section'), self.link(self.section))
        self.assertEqual(self.client.get(self.change_url(self.section)).status_code, 200)

    def test_foreign_key_without_target_permission(self):
        self.grant('view_article')
        response = self.client.get(self.change_url(self.article))
        self.assertHTMLEqual(self.contents(response, 'section'), '&lt;Section &amp; details&gt;')

    def test_foreign_key_change_permission(self):
        self.grant('view_article', 'change_section')
        response = self.client.get(self.change_url(self.article))
        self.assertHTMLEqual(self.contents(response, 'section'), self.link(self.section))

    def test_foreign_key_object_permission(self):
        self.grant('view_article', 'view_section')
        with mock.patch.object(site._registry[Section], 'has_view_permission', return_value=False):
            response = self.client.get(self.change_url(self.article))
            self.assertHTMLEqual(self.contents(response, 'section'), '&lt;Section &amp; details&gt;')

    def test_many_to_many_view_permission(self):
        self.grant('view_pizza', 'view_topping')
        response = self.client.get(self.change_url(self.pizza))
        self.assertHTMLEqual(
            self.contents(response, 'toppings'),
            '%s, %s' % (self.link(self.topping), self.link(self.other_topping)),
        )

    def test_many_to_many_object_permission(self):
        self.grant('view_pizza', 'view_topping')
        def can_view(request, obj=None):
            return obj is None or obj.pk == self.topping.pk
        with mock.patch.object(site._registry[Topping], 'has_view_permission', side_effect=can_view):
            response = self.client.get(self.change_url(self.pizza))
            contents = self.contents(response, 'toppings')
        self.assertHTMLEqual(contents, '%s, Olives' % self.link(self.topping))

    def test_readonly_inline_foreign_key(self):
        self.grant('view_article', 'view_section')
        response = self.client.get(self.change_url(self.section))
        self.assertContains(
            response, format_html('<p>{}</p>', self.link(self.other_section)), html=True,
        )

